using System.ComponentModel.DataAnnotations;using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Stock;
[Authorize]public sealed class EditModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public int Id{get;set;}[BindProperty]public StockEditInput Input{get;set;}=new();public string MedicineName{get;private set;}="";public string SupplierName{get;private set;}="";
public async Task<IActionResult>OnGetAsync(CancellationToken ct){var x=await db.StockBatches.Include(x=>x.Medicine).Include(x=>x.Supplier).AsNoTracking().SingleOrDefaultAsync(x=>x.Id==Id,ct);if(x is null)return NotFound();MedicineName=x.Medicine.Name;SupplierName=x.Supplier.Name;Input=new StockEditInput{BatchNumber=x.BatchNumber,Quantity=x.Quantity,PurchasePrice=x.PurchasePrice,ExpiryDate=x.ExpiryDate};return Page();}
public async Task<IActionResult>OnPostAsync(CancellationToken ct){var x=await db.StockBatches.Include(x=>x.Medicine).Include(x=>x.Supplier).SingleOrDefaultAsync(x=>x.Id==Id,ct);if(x is null)return NotFound();MedicineName=x.Medicine.Name;SupplierName=x.Supplier.Name;if(Input.Quantity<0)ModelState.AddModelError("Input.Quantity","Quantity cannot be negative.");if(!ModelState.IsValid)return Page();var difference=Input.Quantity-x.Quantity;if(difference!=0){if(string.IsNullOrWhiteSpace(Input.Reason)){ModelState.AddModelError("Input.Reason","A reason is required for quantity corrections.");return Page();}db.StockAdjustments.Add(new StockAdjustment{StockBatchId=x.Id,QuantityChange=difference,Reason=Input.Reason.Trim(),AdjustedAtUtc=DateTime.UtcNow});}x.BatchNumber=Input.BatchNumber.Trim();x.Quantity=Input.Quantity;x.PurchasePrice=Input.PurchasePrice;x.ExpiryDate=Input.ExpiryDate;await db.SaveChangesAsync(ct);TempData["StatusMessage"]="Stock batch changes saved.";return RedirectToPage("Details",new{id=Id});}}
public sealed class StockEditInput{[Required,StringLength(80)]public string BatchNumber{get;set;}="";[Range(0,100000000)]public int Quantity{get;set;}[Range(typeof(decimal),"0","999999999")]public decimal PurchasePrice{get;set;}[Required]public DateTime ExpiryDate{get;set;}[StringLength(500)]public string?Reason{get;set;}}
